import 'dart:io';
import 'package:flutter/material.dart';
import 'package:file_picker/file_picker.dart';
import 'package:share_plus/share_plus.dart';
import 'package:path_provider/path_provider.dart';
import 'database_service.dart';
import 'main.dart';
class ImportScreen extends StatefulWidget{const ImportScreen({super.key});@override State<ImportScreen> createState()=>_ImportScreenState();}
class _ImportScreenState extends State<ImportScreen>{final controller=TextEditingController();bool busy=false;String status='';
@override void dispose(){controller.dispose();super.dispose();}
Future<void> pick()async{final result=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(result==null)return;final bytes=result.files.single.bytes;if(bytes==null){setState(()=>status='Não foi possível ler o arquivo.');return;}controller.text=String.fromCharCodes(bytes);setState(()=>status='Arquivo carregado: ${result.files.single.name}');}
Future<void> import()async{setState(()=>busy=true);try{final n=await DatabaseService.instance.importJson(controller.text);setState(()=>status='$n questões importadas com sucesso.');}catch(e){setState(()=>status='Erro no JSON: ${e.toString()}');}finally{setState(()=>busy=false);}}
Future<void> export()async{final data=await DatabaseService.instance.exportJson();final dir=await getTemporaryDirectory();final file=File('${dir.path}/concursa_questoes.json');await file.writeAsString(data);await Share.shareXFiles([XFile(file.path)],text:'Backup de questões do Concursa');}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Importar e exportar')),body:ListView(padding:const EdgeInsets.all(18),children:[const Text('Sua base de questões',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Importe um arquivo JSON ou cole uma lista. As questões ficam salvas no aparelho e funcionam offline.'),const SizedBox(height:14),OutlinedButton.icon(onPressed:pick,icon:const Icon(Icons.folder_open),label:const Text('Selecionar arquivo JSON')),TextField(controller:controller,minLines:10,maxLines:16,decoration:const InputDecoration(hintText:'Cole aqui o JSON das questões...',alignLabelWithHint:true)),const SizedBox(height:12),FilledButton(onPressed:busy?null:import,child:Text(busy?'Importando...':'Importar questões')),OutlinedButton.icon(onPressed:export,icon:const Icon(Icons.ios_share),label:const Text('Exportar backup JSON')),if(status.isNotEmpty)Padding(padding:const EdgeInsets.only(top:12),child:Text(status,style:const TextStyle(color:lime))),const SizedBox(height:20),const Text('Formato aceito',style:TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:8),const SelectableText('[\\n  {\\n    "prompt": "Enunciado da questão",\\n    "optionA": "Alternativa A",\\n    "optionB": "Alternativa B",\\n    "optionC": "Alternativa C",\\n    "optionD": "Alternativa D",\\n    "optionE": "Alternativa E",\\n    "answer": "B",\\n    "explanation": "Explicação do gabarito",\\n    "subject": "Português",\\n    "board": "Banca",\\n    "exam": "Cargo/Prova",\\n    "year": "2025",\\n    "difficulty": "Média",\\n    "source": "Referência da questão"\\n  }\\n]'),const SizedBox(height:12),const Text('Importante: esta versão não extrai automaticamente perguntas de PDFs. Só importe material que você tenha direito de usar; os exemplos iniciais são demonstrativos, não questões oficiais do PCI Concursos.',style:TextStyle(color:Colors.white60,fontSize:12))]));}
